package com.example.starter.domain;

import java.time.Instant;

/**
 * 风电机组。
 * ratedPowerKw 装机容量（kW）；technicalMinKw 技术出力下限（kW，额定的 15%）；
 * availablePowerKw 最新可用出力（kW），随执行回报刷新。
 */
public class Turbine {

    private Long id;
    private String farmCode;
    private String turbineCode;
    private int ratedPowerKw;
    private int technicalMinKw;
    private int availablePowerKw;
    private Instant updatedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getFarmCode() {
        return farmCode;
    }

    public void setFarmCode(String farmCode) {
        this.farmCode = farmCode;
    }

    public String getTurbineCode() {
        return turbineCode;
    }

    public void setTurbineCode(String turbineCode) {
        this.turbineCode = turbineCode;
    }

    public int getRatedPowerKw() {
        return ratedPowerKw;
    }

    public void setRatedPowerKw(int ratedPowerKw) {
        this.ratedPowerKw = ratedPowerKw;
    }

    public int getTechnicalMinKw() {
        return technicalMinKw;
    }

    public void setTechnicalMinKw(int technicalMinKw) {
        this.technicalMinKw = technicalMinKw;
    }

    public int getAvailablePowerKw() {
        return availablePowerKw;
    }

    public void setAvailablePowerKw(int availablePowerKw) {
        this.availablePowerKw = availablePowerKw;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 限电指令。
 * requestId 外部请求幂等键（全局唯一）；fingerprint 覆盖 requestId 与全部业务字段的指纹；
 * status 当前生命周期状态；currentCycleNo 当前执行轮次（初次下发为 1，告警重分摊递增）；
 * supersededByOrderId 作废本指令的新指令 id（非空表示已被新指令原子切换）。
 */
public class CurtailOrder {

    private Long id;
    private String orderNo;
    private String farmCode;
    private String requestId;
    private String fingerprint;
    private int targetPowerKw;
    private OrderStatus status;
    private int currentCycleNo;
    private Long supersededByOrderId;
    private Instant receivedAt;
    private Instant settledAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getOrderNo() {
        return orderNo;
    }

    public void setOrderNo(String orderNo) {
        this.orderNo = orderNo;
    }

    public String getFarmCode() {
        return farmCode;
    }

    public void setFarmCode(String farmCode) {
        this.farmCode = farmCode;
    }

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public String getFingerprint() {
        return fingerprint;
    }

    public void setFingerprint(String fingerprint) {
        this.fingerprint = fingerprint;
    }

    public int getTargetPowerKw() {
        return targetPowerKw;
    }

    public void setTargetPowerKw(int targetPowerKw) {
        this.targetPowerKw = targetPowerKw;
    }

    public OrderStatus getStatus() {
        return status;
    }

    public void setStatus(OrderStatus status) {
        this.status = status;
    }

    public int getCurrentCycleNo() {
        return currentCycleNo;
    }

    public void setCurrentCycleNo(int currentCycleNo) {
        this.currentCycleNo = currentCycleNo;
    }

    public Long getSupersededByOrderId() {
        return supersededByOrderId;
    }

    public void setSupersededByOrderId(Long supersededByOrderId) {
        this.supersededByOrderId = supersededByOrderId;
    }

    public Instant getReceivedAt() {
        return receivedAt;
    }

    public void setReceivedAt(Instant receivedAt) {
        this.receivedAt = receivedAt;
    }

    public Instant getSettledAt() {
        return settledAt;
    }

    public void setSettledAt(Instant settledAt) {
        this.settledAt = settledAt;
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 下发轮次：每次分摊下发（含告警后重分摊）生成一轮。
 * dueAt 下发后满 10 分钟的判定时刻（恰满即判定）。
 */
public class DispatchCycle {

    private Long id;
    private Long orderId;
    private int cycleNo;
    private Instant dispatchedAt;
    private Instant dueAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getOrderId() {
        return orderId;
    }

    public void setOrderId(Long orderId) {
        this.orderId = orderId;
    }

    public int getCycleNo() {
        return cycleNo;
    }

    public void setCycleNo(int cycleNo) {
        this.cycleNo = cycleNo;
    }

    public Instant getDispatchedAt() {
        return dispatchedAt;
    }

    public void setDispatchedAt(Instant dispatchedAt) {
        this.dispatchedAt = dispatchedAt;
    }

    public Instant getDueAt() {
        return dueAt;
    }

    public void setDueAt(Instant dueAt) {
        this.dueAt = dueAt;
    }
}

package com.example.starter.domain;

/**
 * 单机分摊结果（某一轮次）。
 * baseAvailableKw 分摊时该机组可用出力；targetPowerKw 分摊后保留出力目标；
 * curtailKw 压减出力；targetPowerKw 不低于技术出力下限。
 */
public class Allocation {

    private Long id;
    private Long orderId;
    private int cycleNo;
    private Long turbineId;
    private int baseAvailableKw;
    private int targetPowerKw;
    private int curtailKw;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getOrderId() {
        return orderId;
    }

    public void setOrderId(Long orderId) {
        this.orderId = orderId;
    }

    public int getCycleNo() {
        return cycleNo;
    }

    public void setCycleNo(int cycleNo) {
        this.cycleNo = cycleNo;
    }

    public Long getTurbineId() {
        return turbineId;
    }

    public void setTurbineId(Long turbineId) {
        this.turbineId = turbineId;
    }

    public int getBaseAvailableKw() {
        return baseAvailableKw;
    }

    public void setBaseAvailableKw(int baseAvailableKw) {
        this.baseAvailableKw = baseAvailableKw;
    }

    public int getTargetPowerKw() {
        return targetPowerKw;
    }

    public void setTargetPowerKw(int targetPowerKw) {
        this.targetPowerKw = targetPowerKw;
    }

    public int getCurtailKw() {
        return curtailKw;
    }

    public void setCurtailKw(int curtailKw) {
        this.curtailKw = curtailKw;
    }
}

