                    ps.setInt(2, cycleNo);
                    ps.setLong(3, a.getTurbineId());
                    ps.setInt(4, a.getBaseAvailableKw());
                    ps.setInt(5, a.getTargetPowerKw());
                    ps.setInt(6, a.getCurtailKw());
                });
